function handsUp(x, y, h, col = '#030405', rim = 'rgba(255,240,210,.35)') { const u = h / 100; ctx.fillStyle = col; ctx.beginPath(); ctx.ellipse(x, y - 88 * u, 8 * u, 9.5 * u, 0, 0, 7); ctx.fill(); ctx.beginPath(); ctx.moveTo(x - 15 * u, y - 78 * u); ctx.lineTo(x + 15 * u, y - 78 * u); ctx.lineTo(x + 12 * u, y - 44 * u); ctx.lineTo(x + 9 * u, y); ctx.lineTo(x + 2 * u, y); ctx.lineTo(x, y - 40 * u); ctx.lineTo(x - 2 * u, y); ctx.lineTo(x - 9 * u, y); ctx.lineTo(x - 12 * u, y - 44 * u); ctx.closePath(); ctx.fill();
  ctx.strokeStyle = col; ctx.lineCap = 'round'; ctx.lineWidth = 7 * u; for (const k of [-1, 1]) { ctx.beginPath(); ctx.moveTo(x + k * 13 * u, y - 75 * u); ctx.lineTo(x + k * 22 * u, y - 96 * u); ctx.lineTo(x + k * 20 * u, y - 118 * u); ctx.stroke(); } ctx.strokeStyle = rim; ctx.lineWidth = 1.2 * u; ctx.beginPath(); ctx.ellipse(x, y - 88 * u, 8.5 * u, 10 * u, 0, 0, 7); ctx.stroke(); }
