    if (k === 1) { ctx.save(); camKeys(t, [[m[0] - .05, 640, 1300, 1.2], [m[1], 600, 1300, 1.3]], .4); forestNight(t, {}, () => { suvSide(560, 1560, .9, { wheelRot: 0 }); const dp = eout(prog(t, m[0], m[0] + .4)); for (const dx of [440, 200]) { const bx = 560 + (dx - 560) * .9 + 50; ctx.fillStyle = '#050608'; ctx.beginPath(); ctx.moveTo(bx, 1220); ctx.lineTo(bx + 120 * dp, 1200); ctx.lineTo(bx + 120 * dp, 1470); ctx.lineTo(bx, 1480); ctx.fill(); ctx.strokeStyle = 'rgba(150,180,235,.35)'; ctx.lineWidth = 3; ctx.beginPath(); ctx.moveTo(bx, 1220); ctx.lineTo(bx + 120 * dp, 1200); ctx.stroke(); } }); ctx.restore(); vign(.45); bigTitleFit('ХЛОПАЮТ ДВЕРИ', 300, prog(t, m[0] - .05, m[0] + .2), { size: 120, col: '#fff' }); return; }
