    if (k === 1) { const f = Math.max(0, 1 - (t - m[0]) / .2); ctx.save(); camKeys(t, [[m[0] - .05, 420, 1250, 1.4], [m[1], 420, 1250, 1.5]], .3); shake(t, 26 * f); forestNight(t, {}); ctx.save(); ctx.globalCompositeOperation = 'lighter'; glow(260, 1300, 120 + 900 * f, `rgba(255,240,200,${.4 + .6 * f})`); lensFlare(260, 1300, 30, .3 + .7 * f); ctx.restore(); ctx.restore(); if (f > 0) { ctx.fillStyle = `rgba(255,250,235,${.8 * f})`; ctx.fillRect(0, 0, W, H); } vign(.5); bigTitleFit('ВЫСТРЕЛ', 300, 1, { size: 150, col: '#ff4d4d' }); return; }
